from __future__ import annotations

def relu(x: float) -> float:
    return max(x, 0.0)

def tent(x: float) -> float:
    "The tent map as an exact width-2 ReLU layer: 1 - relu(2x-1) - relu(1-2x)."
    return 1.0 - relu(2.0 * x - 1.0) - relu(1.0 - 2.0 * x)

def tent_iterate(x: float, k: int) -> float:
    "Depth-k tent network: tent composed with itself k times (O(k) work)."
    for _ in range(k):
        x = tent(x)
    return x

# tent^[k] climbs from 0 to 1 over an interval of width 2^-k.
for k in range(1, 11):
    left = tent_iterate(0.0, k)
    peak = tent_iterate((0.5) ** k, k)
    print(f"k={k:2d}  tent^k(0)={left:.4f}  tent^k(2^-k)={peak:.4f}  ramp width={(0.5)**k:.3e}")

