def empirical_lipschitz(f, samples):
    grid = [i / (samples - 1) for i in range(samples)]
    return max(abs(f(b) - f(a)) / (b - a) for a, b in zip(grid, grid[1:]))

# Empirical Lipschitz constant of tent^[k] equals the proven value 2^k.
for k in range(1, 11):
    emp = empirical_lipschitz(lambda x: tent_iterate(x, k), 4 * 2**k + 1)
    print(f"k={k:2d}  2^k={2**k:5d}  empirical={emp:.2f}")

