def separation_witness(g, K, eps, k):
    "Return (fails, max_error). By relu_depth_separation, fails is True when K*2^-k+2eps<1."
    assert K * (0.5) ** k + 2.0 * eps < 1.0
    a = abs(tent_iterate(0.0, k) - g(0.0))
    b = abs(tent_iterate((0.5) ** k, k) - g((0.5) ** k))
    return (max(a, b) > eps, max(a, b))

# The constant 1/2 (K=0) cannot approximate the depth-3 tent to accuracy 3/8.
print(separation_witness(lambda x: 0.5, K=0.0, eps=3/8, k=3))   # (True, 0.5)
# A slope-4 line cannot approximate the depth-8 tent to accuracy 0.05.
print(separation_witness(lambda x: 4*x, K=4.0, eps=0.05, k=8))  # (True, ~0.98)

